DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_students` ()   BEGIN

    DECLARE dept_done INT DEFAULT 0;
    DECLARE dept_id_value INT;
    DECLARE dept_name_value VARCHAR(100);

    DECLARE student_num INT;
    DECLARE male_index INT;
    DECLARE female_index INT;

    DECLARE dept_cursor CURSOR FOR
        SELECT dept_id, dept_name
        FROM department
        WHERE dept_name IN
        (
            'CSE',
            'IT',
            'ECE',
            'EEE',
            'MECH',
            'AIDS',
            'AIML',
            'CYBER',
            'FOOD TECH',
            'BIOTECH',
            'BME',
            'AGRI',
            'VLSI',
            'CIVIL'
        );

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET dept_done = 1;


    OPEN dept_cursor;


    department_loop:LOOP

        FETCH dept_cursor
        INTO dept_id_value, dept_name_value;


        IF dept_done = 1 THEN
            LEAVE department_loop;
        END IF;


        SET student_num = 1;


        student_loop: LOOP

            IF student_num > 200 THEN
                LEAVE student_loop;
            END IF;


            /* Register Number */

            INSERT INTO student
            (
                register_no,
                password,
                must_change_password,
                student_name,
                dept_id,
                year,
                gender
            )

            VALUES
            (

                CONCAT(
                    CASE dept_name_value

                        WHEN 'CSE' THEN 'CSE'
                        WHEN 'IT' THEN 'IT'
                        WHEN 'ECE' THEN 'ECE'
                        WHEN 'EEE' THEN 'EEE'
                        WHEN 'MECH' THEN 'MECH'
                        WHEN 'AIDS' THEN 'AIDS'
                        WHEN 'AIML' THEN 'AIML'
                        WHEN 'CYBER' THEN 'CYBER'
                        WHEN 'FOOD TECH' THEN 'FT'
                        WHEN 'BIOTECH' THEN 'BT'
                        WHEN 'BME' THEN 'BME'
                        WHEN 'AGRI' THEN 'AGRI'
                        WHEN 'VLSI' THEN 'VLSI'
                        WHEN 'CIVIL' THEN 'CIVIL'

                    END,

                    LPAD(student_num,3,'0')
                ),


                'temp@2025',


                1,


                CASE

                    /* 100 MALE */

                    WHEN student_num <= 100 THEN

                        CONCAT(

                            ELT(
                                MOD(student_num - 1,20) + 1,

                                'Aarav',
                                'Arjun',
                                'Aditya',
                                'Rahul',
                                'Vignesh',
                                'Karthik',
                                'Rohit',
                                'Vijay',
                                'Sanjay',
                                'Praveen',
                                'Ashwin',
                                'Surya',
                                'Manoj',
                                'Dinesh',
                                'Hari',
                                'Gokul',
                                'Naveen',
                                'Vishal',
                                'Aravind',
                                'Suresh'
                            ),

                            ' ',

                            ELT(
                                FLOOR((student_num - 1) / 20) + 1,

                                'Kumar',
                                'Raj',
                                'Sharma',
                                'Prasad',
                                'Das'
                            )

                        )


                    /* 100 FEMALE */

                    ELSE

                        CONCAT(

                            ELT(
                                MOD(student_num - 101,20) + 1,

                                'Ananya',
                                'Diya',
                                'Harini',
                                'Priya',
                                'Sneha',
                                'Keerthana',
                                'Pooja',
                                'Kavya',
                                'Divya',
                                'Nisha',
                                'Aishwarya',
                                'Swetha',
                                'Lavanya',
                                'Anjali',
                                'Shalini',
                                'Gayathri',
                                'Reshma',
                                'Nandhini',
                                'Sowmya',
                                'Pavithra'
                            ),

                            ' ',

                            ELT(
                                FLOOR((student_num - 101) / 20) + 1,

                                'Kumar',
                                'Raj',
                                'Sharma',
                                'Prasad',
                                'Das'
                            )

                        )

                END,


                dept_id_value,


                2,


                CASE

                    WHEN student_num <= 100
                    THEN 'MALE'

                    ELSE 'FEMALE'

                END

            );


            SET student_num = student_num + 1;


        END LOOP student_loop;


    END LOOP department_loop;


    CLOSE dept_cursor;

END$$

DELIMITER ;

